#!/usr/bin/env python3
"""
Minimal agentic loop using Anthropic API with bash execution and human confirmation.
"""

import os
import sys
import json
import subprocess
from typing import Dict, List, Optional
from anthropic import Anthropic

# Initialize Anthropic client
client = Anthropic(api_key=os.environ.get("ANTHROPIC_API_KEY"))

def run_bash_command(command: str) -> Dict[str, any]:
    """Execute a bash command and return the result."""
    try:
        result = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )
        return {
            "success": True,
            "stdout": result.stdout,
            "stderr": result.stderr,
            "return_code": result.returncode
        }
    except subprocess.TimeoutExpired:
        return {
            "success": False,
            "error": "Command timed out after 30 seconds"
        }
    except Exception as e:
        return {
            "success": False,
            "error": str(e)
        }

def get_human_confirmation(command: str) -> bool:
    """Ask for human confirmation before executing a command."""
    print(f"\n{'='*60}")
    print(f"The agent wants to execute the following command:")
    print(f"\n  {command}\n")

    while True:
        response = input("Do you want to execute this command? (yes/no): ").lower().strip()
        if response in ['yes', 'y']:
            return True
        elif response in ['no', 'n']:
            return False
        else:
            print("Please answer 'yes' or 'no'")

def process_tool_calls(response) -> List[Dict]:
    """Process tool calls from the assistant's response."""
    results = []

    if not response.content:
        return results

    for content in response.content:
        if content.type == "tool_use" and content.name == "run_bash":
            command = content.input.get("command", "")

            # Get human confirmation
            if get_human_confirmation(command):
                print("\nExecuting command...")
                result = run_bash_command(command)

                # Display result
                if result["success"]:
                    print(f"\nCommand executed successfully (return code: {result.get('return_code', 0)})")
                    if result.get("stdout"):
                        print(f"Output:\n{result['stdout']}")
                    if result.get("stderr"):
                        print(f"Errors:\n{result['stderr']}")
                else:
                    print(f"\nCommand failed: {result.get('error', 'Unknown error')}")

                results.append({
                    "tool_use_id": content.id,
                    "content": json.dumps(result)
                })
            else:
                print("\nCommand execution cancelled by user.")
                results.append({
                    "tool_use_id": content.id,
                    "content": json.dumps({
                        "success": False,
                        "error": "Command execution cancelled by user"
                    })
                })

    return results

def run_agent_loop():
    """Main agent loop."""
    print("Minimal Agent Loop with Bash Execution")
    print("="*60)
    print("Type 'exit' or 'quit' to end the session\n")

    messages = []

    # Define the bash tool
    tools = [
        {
            "name": "run_bash",
            "description": "Execute a bash command. Requires human confirmation before execution.",
            "input_schema": {
                "type": "object",
                "properties": {
                    "command": {
                        "type": "string",
                        "description": "The bash command to execute"
                    }
                },
                "required": ["command"]
            }
        }
    ]

    while True:
        # Get user input
        user_input = input("\nYou: ").strip()

        if user_input.lower() in ['exit', 'quit']:
            print("\nGoodbye!")
            break

        if not user_input:
            continue

        # Add user message
        messages.append({
            "role": "user",
            "content": user_input
        })

        try:
            # Get assistant response
            print("\nAssistant: ", end="", flush=True)

            response = client.messages.create(
                model="claude-3-5-sonnet-20241022",
                messages=messages,
                tools=tools,
                max_tokens=4096
            )

            # Display text response
            for content in response.content:
                if content.type == "text":
                    print(content.text)

            # Add assistant message to history
            messages.append({
                "role": "assistant",
                "content": response.content
            })

            # Process any tool calls
            tool_results = process_tool_calls(response)

            # If there were tool calls, send results back
            if tool_results:
                messages.append({
                    "role": "user",
                    "content": [
                        {
                            "type": "tool_result",
                            "tool_use_id": result["tool_use_id"],
                            "content": result["content"]
                        }
                        for result in tool_results
                    ]
                })

                # Get follow-up response
                print("\nAssistant: ", end="", flush=True)
                follow_up = client.messages.create(
                    model="claude-3-5-sonnet-20241022",
                    messages=messages,
                    tools=tools,
                    max_tokens=4096
                )

                # Display follow-up response
                for content in follow_up.content:
                    if content.type == "text":
                        print(content.text)

                # Add to message history
                messages.append({
                    "role": "assistant",
                    "content": follow_up.content
                })

        except KeyboardInterrupt:
            print("\n\nInterrupted by user")
            break
        except Exception as e:
            print(f"\nError: {e}")

if __name__ == "__main__":
    # Check for API key
    if not os.environ.get("ANTHROPIC_API_KEY"):
        print("Error: ANTHROPIC_API_KEY environment variable not set")
        print("Please set it with: export ANTHROPIC_API_KEY='your-api-key'")
        sys.exit(1)

    try:
        run_agent_loop()
    except KeyboardInterrupt:
        print("\n\nGoodbye!")

